#include <stdio.h>

int main(void) {
    FILE *file = tmpfile();
    if (file == NULL) return 1;
    if (fputs("temporary data", file) == EOF) { fclose(file); return 1; }
    rewind(file);
    char line[32];
    if (fgets(line, sizeof line, file) != NULL) puts(line);
    if (fclose(file) == EOF) return 1;
    return 0;
}
